import { test, expect } from '@playwright/test';

test.describe('Bottom Sheet Mobile Dropdown Replacement', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('http://localhost:3000');

    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });
  });

  test('should display bottom sheet instead of dropdown on mobile', async ({ page }) => {
    // Find and click on a dropdown trigger element
    const dropdownTrigger = page.getByRole('button', { name: /select option/i });
    await dropdownTrigger.click();

    // Verify bottom sheet appears instead of traditional dropdown
    const bottomSheet = page.getByRole('dialog');
    await expect(bottomSheet).toBeVisible();

    // Verify bottom sheet is positioned at the bottom of the screen
    const boundingBox = await bottomSheet.boundingBox();
    expect(boundingBox?.y).toBeGreaterThan(300); // Should be in lower portion of screen

    // Verify bottom sheet has proper styling for mobile
    const computeStyle = await bottomSheet.evaluate((el) => {
      return window.getComputedStyle(el);
    });
    expect(computeStyle.position).toBe('fixed');
  });

  test('should allow selection from bottom sheet options', async ({ page }) => {
    // Click dropdown trigger
    const dropdownTrigger = page.getByRole('button', { name: /select option/i });
    await dropdownTrigger.click();

    // Wait for bottom sheet to appear
    const bottomSheet = page.getByRole('dialog');
    await expect(bottomSheet).toBeVisible();

    // Select an option from the bottom sheet
    const optionToSelect = page.getByRole('option', { name: /option 1/i });
    await optionToSelect.click();

    // Verify bottom sheet closes after selection
    await expect(bottomSheet).not.toBeVisible();

    // Verify the selected value is displayed in the trigger button
    await expect(dropdownTrigger).toContainText('Option 1');
  });

  test('should close bottom sheet when clicking outside or cancel button', async ({ page }) => {
    // Click dropdown trigger
    const dropdownTrigger = page.getByRole('button', { name: /select option/i });
    await dropdownTrigger.click();

    // Verify bottom sheet is visible
    const bottomSheet = page.getByRole('dialog');
    await expect(bottomSheet).toBeVisible();

    // Find and click cancel button
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await cancelButton.click();

    // Verify bottom sheet closes
    await expect(bottomSheet).not.toBeVisible();
  });

  test('should display all options in bottom sheet with proper scrolling', async ({ page }) => {
    // Click dropdown trigger
    const dropdownTrigger = page.getByRole('button', { name: /select option/i });
    await dropdownTrigger.click();

    // Verify bottom sheet appears
    const bottomSheet = page.getByRole('dialog');
    await expect(bottomSheet).toBeVisible();

    // Get all options in the bottom sheet
    const options = page.getByRole('option');
    const optionCount = await options.count();
    expect(optionCount).toBeGreaterThan(0);

    // Verify options are visible and scrollable
    const firstOption = page.getByRole('option').first();
    await expect(firstOption).toBeVisible();

    // Scroll to last option if needed
    const lastOption = page.getByRole('option').last();
    await lastOption.scrollIntoViewIfNeeded();
    await expect(lastOption).toBeVisible();
  });

  test('should maintain bottom sheet state during orientation changes', async ({ page }) => {
    // Click dropdown trigger
    const dropdownTrigger = page.getByRole('button', { name: /select option/i });
    await dropdownTrigger.click();

    // Verify bottom sheet is visible
    const bottomSheet = page.getByRole('dialog');
    await expect(bottomSheet).toBeVisible();

    // Simulate orientation change to landscape
    await page.setViewportSize({ width: 667, height: 375 });

    // Verify bottom sheet is still visible and properly positioned
    await expect(bottomSheet).toBeVisible();
    const boundingBox = await bottomSheet.boundingBox();
    expect(boundingBox?.width).toBeGreaterThan(300);
  });

  test('should show bottom sheet with proper accessibility attributes', async ({ page }) => {
    // Click dropdown trigger
    const dropdownTrigger = page.getByRole('button', { name: /select option/i });
    await dropdownTrigger.click();

    // Verify bottom sheet has proper ARIA attributes
    const bottomSheet = page.getByRole('dialog');
    await expect(bottomSheet).toHaveAttribute('role', 'dialog');

    // Verify options have proper ARIA roles
    const options = page.getByRole('option');
    const firstOption = options.first();
    await expect(firstOption).toHaveAttribute('role', 'option');

    // Verify bottom sheet can be closed with Escape key
    await page.keyboard.press('Escape');
    await expect(bottomSheet).not.toBeVisible();
  });

  test('should handle multiple bottom sheet instances independently', async ({ page }) => {
    // Click first dropdown trigger
    const firstDropdown = page.getByRole('button', { name: /select option/i }).first();
    await firstDropdown.click();

    // Verify first bottom sheet appears
    const bottomSheets = page.getByRole('dialog');
    const firstSheetCount = await bottomSheets.count();
    expect(firstSheetCount).toBeGreaterThan(0);

    // Select an option from first bottom sheet
    const firstOption = page.getByRole('option', { name: /option 1/i }).first();
    await firstOption.click();

    // Verify first bottom sheet closes
    await expect(bottomSheets.first()).not.toBeVisible();

    // Click second dropdown trigger if available
    const secondDropdown = page.getByRole('button', { name: /select option/i }).nth(1);
    if (await secondDropdown.isVisible()) {
      await secondDropdown.click();
      const secondSheet = page.getByRole('dialog');
      await expect(secondSheet).toBeVisible();
    }
  });

  test('should display bottom sheet with smooth animation on mobile', async ({ page }) => {
    // Click dropdown trigger
    const dropdownTrigger = page.getByRole('button', { name: /select option/i });
    await dropdownTrigger.click();

    // Verify bottom sheet appears with animation
    const bottomSheet = page.getByRole('dialog');

    // Check for animation properties
    const animationStyle = await bottomSheet.evaluate((el) => {
      return window.getComputedStyle(el);
    });

    // Verify animation or transition is applied
    const hasAnimation = animationStyle.animation !== 'none' || 
                        animationStyle.transition !== 'none';
    expect(hasAnimation).toBeTruthy();

    // Verify bottom sheet is fully visible after animation
    await expect(bottomSheet).toBeVisible();
  });
});
